CREATE TABLE relay_meta (singleton integer PRIMARY KEY CHECK (singleton = 1), server_id bytea NOT NULL, fence text NOT NULL);
CREATE TABLE bootstrap_token (hash bytea PRIMARY KEY, expires bigint NOT NULL);
CREATE TABLE principal (id uuid PRIMARY KEY, signing bytea NOT NULL, recipient bytea NOT NULL, UNIQUE(signing), UNIQUE(recipient));
CREATE TABLE household (id uuid PRIMARY KEY, genesis bytea NOT NULL, epoch bigint NOT NULL CHECK(epoch > 0), manifest_hash bytea NOT NULL, body bytea NOT NULL, frozen boolean NOT NULL DEFAULT false);
CREATE TABLE membership (household uuid NOT NULL REFERENCES household(id), device uuid NOT NULL REFERENCES principal(id), member uuid NOT NULL, role text NOT NULL CHECK(role IN ('owner','editor','recovery')), active boolean NOT NULL, PRIMARY KEY(household,device));
CREATE INDEX membership_device ON membership(device);
CREATE TABLE manifest (household uuid NOT NULL REFERENCES household(id), epoch bigint NOT NULL, proof bytea NOT NULL, PRIMARY KEY(household,epoch));
CREATE TABLE auth_challenge (id uuid PRIMARY KEY, device uuid NOT NULL, purpose text NOT NULL, nonce bytea NOT NULL, signing bytea NOT NULL, expires bigint NOT NULL);
CREATE TABLE auth_session (hash bytea PRIMARY KEY, device uuid NOT NULL REFERENCES principal(id), kind text NOT NULL CHECK(kind IN ('device','recovery')), expires bigint NOT NULL, revoked boolean NOT NULL DEFAULT false);
CREATE TABLE invitation (id uuid PRIMARY KEY, household uuid NOT NULL REFERENCES household(id), hash bytea NOT NULL, member uuid NOT NULL, role text NOT NULL, expires bigint NOT NULL, consumed boolean NOT NULL DEFAULT false);
CREATE TABLE join_request (id uuid PRIMARY KEY, household uuid NOT NULL REFERENCES household(id), invite uuid NOT NULL REFERENCES invitation(id), assertion bytea NOT NULL, signature bytea NOT NULL, expires bigint NOT NULL, denied boolean NOT NULL DEFAULT false);
CREATE TABLE shared_list (id uuid PRIMARY KEY, household uuid NOT NULL REFERENCES household(id), last_seq bigint NOT NULL DEFAULT 0 CHECK(last_seq >= 0), head bytea NOT NULL, storage_bytes bigint NOT NULL DEFAULT 0);
CREATE INDEX shared_list_household ON shared_list(household);
CREATE TABLE operation (list uuid NOT NULL REFERENCES shared_list(id), seq bigint NOT NULL CHECK(seq > 0), intent uuid NOT NULL, envelope uuid NOT NULL, digest bytea NOT NULL, data bytea NOT NULL, receipt bytea NOT NULL, head bytea NOT NULL, PRIMARY KEY(list,seq), UNIQUE(list,intent), UNIQUE(list,envelope));
CREATE TABLE snapshot_candidate (id uuid PRIMARY KEY, household uuid NOT NULL REFERENCES household(id), list uuid NOT NULL, author uuid NOT NULL REFERENCES principal(id), epoch bigint NOT NULL, seq bigint NOT NULL, head bytea NOT NULL, digest bytea NOT NULL, data bytea NOT NULL, expires bigint NOT NULL);
CREATE INDEX snapshot_candidate_list ON snapshot_candidate(household,list);
CREATE TABLE published_snapshot (list uuid NOT NULL REFERENCES shared_list(id), epoch bigint NOT NULL, seq bigint NOT NULL, head bytea NOT NULL, data bytea NOT NULL, PRIMARY KEY(list,epoch));
CREATE TABLE key_package (household uuid NOT NULL REFERENCES household(id), epoch bigint NOT NULL, list uuid NOT NULL REFERENCES shared_list(id), recipient bytea NOT NULL, data bytea NOT NULL, PRIMARY KEY(household,epoch,list,recipient));
CREATE TABLE rate_bucket (key bytea PRIMARY KEY, minute bigint NOT NULL, count integer NOT NULL);
